   278  /**
   279   * compactCells takes a set of hexagons all at the same resolution and
   280   * compresses them by pruning full child branches to the parent level. This is
   281   * also done for all parents recursively to get the minimum number of hex
   282   * addresses that perfectly cover the defined space.
   283   * @param h3Set Set of hexagons
   284   * @param compactedSet The output array of compressed hexagons (preallocated)
   285   * @param numHexes The size of the input and output arrays (possible that no
   286   * contiguous regions exist in the set at all and no compression possible)
   287   * @return an error code on bad input data
   288   */
   289  // todo: update internal implementation for int64_t
   290  H3Error H3_EXPORT(compactCells)(const H3Index *h3Set, H3Index *compactedSet,
   291                                  const int64_t numHexes) {
   292      if (numHexes == 0) {
   293          return E_SUCCESS;
   294      }
   295      int res = H3_GET_RESOLUTION(h3Set[0]);
   296      if (res == 0) {
   297          // No compaction possible, just copy the set to output
   298          for (int i = 0; i < numHexes; i++) {
   299              compactedSet[i] = h3Set[i];
   300          }
   301          return E_SUCCESS;
   302      }
   303      H3Index *remainingHexes = H3_MEMORY(malloc)(numHexes * sizeof(H3Index));
   304      if (!remainingHexes) {
   305          return E_MEMORY;
   306      }
   307      memcpy(remainingHexes, h3Set, numHexes * sizeof(H3Index));
   308      H3Index *hashSetArray = H3_MEMORY(calloc)(numHexes, sizeof(H3Index));
   309      if (!hashSetArray) {
   310          H3_MEMORY(free)(remainingHexes);
   311          return E_MEMORY;
   312      }
   313      H3Index *compactedSetOffset = compactedSet;
   314      int numRemainingHexes = numHexes;
   315      while (numRemainingHexes) {
   316          res = H3_GET_RESOLUTION(remainingHexes[0]);
   317          int parentRes = res - 1;
   318          // Put the parents of the hexagons into the temp array
   319          // via a hashing mechanism, and use the reserved bits
   320          // to track how many times a parent is duplicated
   321          for (int i = 0; i < numRemainingHexes; i++) {
   322              H3Index currIndex = remainingHexes[i];
   323              if (currIndex != 0) {
   324                  H3Index parent = H3_EXPORT(cellToParent)(currIndex, parentRes);
   325                  // Modulus hash the parent into the temp array
   326                  int loc = (int)(parent % numRemainingHexes);
   327                  int loopCount = 0;
   328                  while (hashSetArray[loc] != 0) {
   329                      if (loopCount > numRemainingHexes) {  // LCOV_EXCL_BR_LINE
   330                          // LCOV_EXCL_START
   331                          // This case should not be possible because at most one
   332                          // index is placed into hashSetArray per
   333                          // numRemainingHexes.
   334                          H3_MEMORY(free)(remainingHexes);
   335                          H3_MEMORY(free)(hashSetArray);
   336                          return E_FAILED;
   337                          // LCOV_EXCL_STOP
   338                      }
   339                      H3Index tempIndex =
   340                          hashSetArray[loc] & H3_RESERVED_MASK_NEGATIVE;
   341                      if (tempIndex == parent) {
   342                          int count = H3_GET_RESERVED_BITS(hashSetArray[loc]) + 1;
   343                          int limitCount = 7;
   344                          if (H3_EXPORT(isPentagon)(tempIndex &
   345                                                    H3_RESERVED_MASK_NEGATIVE)) {
   346                              limitCount--;
   347                          }
   348                          // One is added to count for this check to match one
   349                          // being added to count later in this function when
   350                          // checking for all children being present.
   351                          if (count + 1 > limitCount) {
   352                              // Only possible on duplicate input
   353                              H3_MEMORY(free)(remainingHexes);
   354                              H3_MEMORY(free)(hashSetArray);
   355                              return E_DUPLICATE_INPUT;
   356                          }
   357                          H3_SET_RESERVED_BITS(parent, count);
   358                          hashSetArray[loc] = H3_NULL;
   359                      } else {
   360                          loc = (loc + 1) % numRemainingHexes;
   361                      }
   362                      loopCount++;
   363                  }
   364                  hashSetArray[loc] = parent;
   365              }
   366          }
   367          // Determine which parent hexagons have a complete set
   368          // of children and put them in the compactableHexes array
   369          int compactableCount = 0;
   370          int maxCompactableCount =
   371              numRemainingHexes / 6;  // Somehow all pentagons; conservative
   372          if (maxCompactableCount == 0) {
   373              memcpy(compactedSetOffset, remainingHexes,
   374                     numRemainingHexes * sizeof(remainingHexes[0]));
   375              break;
   376          }
   377          H3Index *compactableHexes =
   378              H3_MEMORY(calloc)(maxCompactableCount, sizeof(H3Index));
   379          if (!compactableHexes) {
   380              H3_MEMORY(free)(remainingHexes);
   381              H3_MEMORY(free)(hashSetArray);
   382              return E_MEMORY;
   383          }
   384          for (int i = 0; i < numRemainingHexes; i++) {
   385              if (hashSetArray[i] == 0) continue;
   386              int count = H3_GET_RESERVED_BITS(hashSetArray[i]) + 1;
   387              // Include the deleted direction for pentagons as implicitly "there"
   388              if (H3_EXPORT(isPentagon)(hashSetArray[i] &
   389                                        H3_RESERVED_MASK_NEGATIVE)) {
   390                  // We need this later on, no need to recalculate
   391                  H3_SET_RESERVED_BITS(hashSetArray[i], count);
   392                  // Increment count after setting the reserved bits,
   393                  // since count is already incremented above, so it
   394                  // will be the expected value for a complete hexagon.
   395                  count++;
   396              }
   397              if (count == 7) {
   398                  // Bingo! Full set!
   399                  compactableHexes[compactableCount] =
   400                      hashSetArray[i] & H3_RESERVED_MASK_NEGATIVE;
   401                  compactableCount++;
   402              }
   403          }
   404          // Uncompactable hexes are immediately copied into the
   405          // output compactedSetOffset
   406          int uncompactableCount = 0;
   407          for (int i = 0; i < numRemainingHexes; i++) {
   408              H3Index currIndex = remainingHexes[i];
   409              if (currIndex != H3_NULL) {
   410                  H3Index parent = H3_EXPORT(cellToParent)(currIndex, parentRes);
   411                  // Modulus hash the parent into the temp array
   412                  // to determine if this index was included in
   413                  // the compactableHexes array
   414                  int loc = (int)(parent % numRemainingHexes);
   415                  int loopCount = 0;
   416                  bool isUncompactable = true;
   417                  do {
   418                      if (loopCount > numRemainingHexes) {  // LCOV_EXCL_BR_LINE
   419                          // LCOV_EXCL_START
   420                          // This case should not be possible because at most one
   421                          // index is placed into hashSetArray per input hexagon.
   422                          H3_MEMORY(free)(compactableHexes);
   423                          H3_MEMORY(free)(remainingHexes);
   424                          H3_MEMORY(free)(hashSetArray);
   425                          return E_FAILED;
   426                          // LCOV_EXCL_STOP
   427                      }
   428                      H3Index tempIndex =
   429                          hashSetArray[loc] & H3_RESERVED_MASK_NEGATIVE;
   430                      if (tempIndex == parent) {
   431                          int count = H3_GET_RESERVED_BITS(hashSetArray[loc]) + 1;
   432                          if (count == 7) {
   433                              isUncompactable = false;
   434                          }
   435                          break;
   436                      } else {
   437                          loc = (loc + 1) % numRemainingHexes;
   438                      }
   439                      loopCount++;
   440                  } while (hashSetArray[loc] != parent);
   441                  if (isUncompactable) {
   442                      compactedSetOffset[uncompactableCount] = remainingHexes[i];
   443                      uncompactableCount++;
   444                  }
   445              }
   446          }
   447          // Set up for the next loop
   448          memset(hashSetArray, 0, numHexes * sizeof(H3Index));
   449          compactedSetOffset += uncompactableCount;
   450          memcpy(remainingHexes, compactableHexes,
   451                 compactableCount * sizeof(H3Index));
   452          numRemainingHexes = compactableCount;
   453          H3_MEMORY(free)(compactableHexes);
   454      }
   455      H3_MEMORY(free)(remainingHexes);
   456      H3_MEMORY(free)(hashSetArray);
   457      return E_SUCCESS;
   458  }
