   491  /**
   492   * uncompactCellsSize takes a compacted set of hexagons and provides
   493   * the exact size of the uncompacted set of hexagons.
   494   *
   495   * @param   compactedSet  Set of hexagons
   496   * @param   numHexes      The number of hexes in the input set
   497   * @param   res           The hexagon resolution to decompress to
   498   * @param   out           The number of hexagons to allocate memory for
   499   * @returns E_SUCCESS on success, or another value on error
   500   */
   501  H3Error H3_EXPORT(uncompactCellsSize)(const H3Index *compactedSet,
   502                                        const int64_t numCompacted, const int res,
   503                                        int64_t *out) {
   504      int64_t numOut = 0;
   505      for (int64_t i = 0; i < numCompacted; i++) {
   506          if (compactedSet[i] == H3_NULL) continue;
   507          if (!_hasChildAtRes(compactedSet[i], res))
   508              return E_RES_MISMATCH;  // Abort
   509
   510          numOut += H3_EXPORT(cellToChildrenSize)(compactedSet[i], res);
   511      }
   512      *out = numOut;
   513      return E_SUCCESS;
   514  }
